// Core components of dynamic relocation

// Load base address of the segment
uint64_t BASE_ADDR = 0x400000;

// Symbol value (resolved target address)
uint64_t SYM_VALUE = 0x4001A0;

// Relocation Entry (R_X86_64_64 example)
uint64_t r_offset = 0x010; // Offset relative to segment start
int64_t r_addend = 0x2000; // Value to add

// Simulated memory segment
uint64_t segment_image[256];

// 1. Calculate the target value to write
uint64_t final_address = SYM_VALUE + r_addend;

// 2. Locate the memory word to patch
uint64_t* patch_loc = segment_image + (r_offset / sizeof(uint64_t));

// 3. Apply the absolute relocation patch
*patch_loc = final_address;
